CREATE TABLE operators (principal TEXT PRIMARY KEY, role TEXT NOT NULL CHECK(role IN ('administrator','officer','reviewer')));
ALTER TABLE audit_log ADD COLUMN operator TEXT;
CREATE TABLE period_events (
    id INTEGER PRIMARY KEY, month TEXT NOT NULL, event TEXT NOT NULL CHECK(event IN ('close','request','reopen')),
    operator TEXT NOT NULL, reason TEXT NOT NULL, bank_cents INTEGER, details TEXT NOT NULL,
    recorded_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX period_event_month ON period_events(month,id);
CREATE TRIGGER closed_ledger_insert BEFORE INSERT ON ledger WHEN COALESCE((SELECT event FROM period_events WHERE month=substr(NEW.date,1,7) ORDER BY id DESC LIMIT 1),'reopen') <> 'reopen' BEGIN SELECT RAISE(ABORT,'This accounting month is closed. Reopen it before editing its postings.'); END;
CREATE TRIGGER closed_ledger_delete BEFORE DELETE ON ledger WHEN COALESCE((SELECT event FROM period_events WHERE month=substr(OLD.date,1,7) ORDER BY id DESC LIMIT 1),'reopen') <> 'reopen' BEGIN SELECT RAISE(ABORT,'This accounting month is closed. Reopen it before editing its postings.'); END;
CREATE TRIGGER closed_ledger_update BEFORE UPDATE ON ledger WHEN (COALESCE((SELECT event FROM period_events WHERE month=substr(OLD.date,1,7) ORDER BY id DESC LIMIT 1),'reopen') <> 'reopen' OR COALESCE((SELECT event FROM period_events WHERE month=substr(NEW.date,1,7) ORDER BY id DESC LIMIT 1),'reopen') <> 'reopen') AND (OLD.id IS NOT NEW.id OR OLD.individual_id IS NOT NEW.individual_id OR OLD.date IS NOT NEW.date OR OLD.event_type IS NOT NEW.event_type OR OLD.loan_id IS NOT NEW.loan_id OR OLD.added IS NOT NEW.added OR OLD.deducted IS NOT NEW.deducted OR OLD.balance IS NOT NEW.balance OR OLD.notes IS NOT NEW.notes OR OLD.installment_amount IS NOT NEW.installment_amount OR OLD.batch_id IS NOT NEW.batch_id OR OLD.interest_amount IS NOT NEW.interest_amount OR OLD.principal_balance IS NOT NEW.principal_balance OR OLD.interest_balance IS NOT NEW.interest_balance OR OLD.principal_portion IS NOT NEW.principal_portion OR OLD.interest_portion IS NOT NEW.interest_portion OR OLD.is_edited IS NOT NEW.is_edited OR OLD.previous_state IS NOT NEW.previous_state OR OLD.import_id IS NOT NEW.import_id OR OLD.gross_balance IS NOT NEW.gross_balance OR OLD.loan_pk IS NOT NEW.loan_pk) BEGIN SELECT RAISE(ABORT,'This accounting month is closed. Reopen it before editing its postings.'); END;
CREATE TABLE ledger_cents (posting_id INTEGER PRIMARY KEY REFERENCES ledger(id) ON DELETE CASCADE, added INTEGER NOT NULL, deducted INTEGER NOT NULL, balance INTEGER NOT NULL, principal_portion INTEGER NOT NULL, interest_portion INTEGER NOT NULL, interest_amount INTEGER NOT NULL, installment_amount INTEGER NOT NULL, principal_balance INTEGER NOT NULL, interest_balance INTEGER NOT NULL);
INSERT INTO ledger_cents SELECT id, CAST(round(added * 100) AS INTEGER), CAST(round(deducted * 100) AS INTEGER), CAST(round(balance * 100) AS INTEGER), CAST(round(principal_portion * 100) AS INTEGER), CAST(round(interest_portion * 100) AS INTEGER), CAST(round(interest_amount * 100) AS INTEGER), CAST(round(installment_amount * 100) AS INTEGER), CAST(round(principal_balance * 100) AS INTEGER), CAST(round(interest_balance * 100) AS INTEGER) FROM ledger;
CREATE TRIGGER exact_ledger_insert AFTER INSERT ON ledger BEGIN INSERT INTO ledger_cents VALUES(NEW.id,CAST(round(NEW.added * 100) AS INTEGER), CAST(round(NEW.deducted * 100) AS INTEGER), CAST(round(NEW.balance * 100) AS INTEGER), CAST(round(NEW.principal_portion * 100) AS INTEGER), CAST(round(NEW.interest_portion * 100) AS INTEGER), CAST(round(NEW.interest_amount * 100) AS INTEGER), CAST(round(NEW.installment_amount * 100) AS INTEGER), CAST(round(NEW.principal_balance * 100) AS INTEGER), CAST(round(NEW.interest_balance * 100) AS INTEGER)) ON CONFLICT(posting_id) DO UPDATE SET added=excluded.added, deducted=excluded.deducted, balance=excluded.balance, principal_portion=excluded.principal_portion, interest_portion=excluded.interest_portion, interest_amount=excluded.interest_amount, installment_amount=excluded.installment_amount, principal_balance=excluded.principal_balance, interest_balance=excluded.interest_balance; END;
CREATE TRIGGER exact_ledger_update AFTER UPDATE OF added, deducted, balance, principal_portion, interest_portion, interest_amount, installment_amount, principal_balance, interest_balance ON ledger BEGIN INSERT INTO ledger_cents VALUES(NEW.id,CAST(round(NEW.added * 100) AS INTEGER), CAST(round(NEW.deducted * 100) AS INTEGER), CAST(round(NEW.balance * 100) AS INTEGER), CAST(round(NEW.principal_portion * 100) AS INTEGER), CAST(round(NEW.interest_portion * 100) AS INTEGER), CAST(round(NEW.interest_amount * 100) AS INTEGER), CAST(round(NEW.installment_amount * 100) AS INTEGER), CAST(round(NEW.principal_balance * 100) AS INTEGER), CAST(round(NEW.interest_balance * 100) AS INTEGER)) ON CONFLICT(posting_id) DO UPDATE SET added=excluded.added, deducted=excluded.deducted, balance=excluded.balance, principal_portion=excluded.principal_portion, interest_portion=excluded.interest_portion, interest_amount=excluded.interest_amount, installment_amount=excluded.installment_amount, principal_balance=excluded.principal_balance, interest_balance=excluded.interest_balance; END;
CREATE TRIGGER closed_savings_insert BEFORE INSERT ON savings WHEN COALESCE((SELECT event FROM period_events WHERE month=substr(NEW.date,1,7) ORDER BY id DESC LIMIT 1),'reopen') <> 'reopen' BEGIN SELECT RAISE(ABORT,'This accounting month is closed. Reopen it before editing its postings.'); END;
