CREATE TRIGGER closed_savings_update BEFORE UPDATE ON savings WHEN (COALESCE((SELECT event FROM period_events WHERE month=substr(OLD.date,1,7) ORDER BY id DESC LIMIT 1),'reopen') <> 'reopen' OR COALESCE((SELECT event FROM period_events WHERE month=substr(NEW.date,1,7) ORDER BY id DESC LIMIT 1),'reopen') <> 'reopen') AND (OLD.id IS NOT NEW.id OR OLD.individual_id IS NOT NEW.individual_id OR OLD.date IS NOT NEW.date OR OLD.transaction_type IS NOT NEW.transaction_type OR OLD.amount IS NOT NEW.amount OR OLD.balance IS NOT NEW.balance OR OLD.notes IS NOT NEW.notes OR OLD.import_id IS NOT NEW.import_id OR OLD.batch_id IS NOT NEW.batch_id OR OLD.created_at IS NOT NEW.created_at) BEGIN SELECT RAISE(ABORT,'This accounting month is closed. Reopen it before editing its postings.'); END;
CREATE TABLE savings_cents (posting_id INTEGER PRIMARY KEY REFERENCES savings(id) ON DELETE CASCADE, amount INTEGER NOT NULL, balance INTEGER NOT NULL);
INSERT INTO savings_cents SELECT id, CAST(round(amount * 100) AS INTEGER), CAST(round(balance * 100) AS INTEGER) FROM savings;
CREATE TRIGGER exact_savings_insert AFTER INSERT ON savings BEGIN INSERT INTO savings_cents VALUES(NEW.id,CAST(round(NEW.amount * 100) AS INTEGER), CAST(round(NEW.balance * 100) AS INTEGER)) ON CONFLICT(posting_id) DO UPDATE SET amount=excluded.amount, balance=excluded.balance; END;
CREATE TRIGGER exact_savings_update AFTER UPDATE OF amount, balance ON savings BEGIN INSERT INTO savings_cents VALUES(NEW.id,CAST(round(NEW.amount * 100) AS INTEGER), CAST(round(NEW.balance * 100) AS INTEGER)) ON CONFLICT(posting_id) DO UPDATE SET amount=excluded.amount, balance=excluded.balance; END;
