CREATE TABLE christmas_savings_cents (posting_id INTEGER PRIMARY KEY REFERENCES christmas_savings(id) ON DELETE CASCADE, amount INTEGER NOT NULL, balance INTEGER NOT NULL);
INSERT INTO christmas_savings_cents SELECT id, CAST(round(amount * 100) AS INTEGER), CAST(round(balance * 100) AS INTEGER) FROM christmas_savings;
CREATE TRIGGER exact_christmas_savings_insert AFTER INSERT ON christmas_savings BEGIN INSERT INTO christmas_savings_cents VALUES(NEW.id,CAST(round(NEW.amount * 100) AS INTEGER), CAST(round(NEW.balance * 100) AS INTEGER)) ON CONFLICT(posting_id) DO UPDATE SET amount=excluded.amount, balance=excluded.balance; END;
