CREATE TABLE benevolent_ledger_cents (posting_id INTEGER PRIMARY KEY REFERENCES benevolent_ledger(id) ON DELETE CASCADE, amount INTEGER NOT NULL, balance INTEGER NOT NULL);
INSERT INTO benevolent_ledger_cents SELECT id, CAST(round(amount * 100) AS INTEGER), CAST(round(balance * 100) AS INTEGER) FROM benevolent_ledger;
